import sys,itertools,random
sys.path.insert(0,'/workspace/tmp')
from ns import NetworkSimplex

def brute(n,arcs):
    # enumerate flows
    ranges=[range(l,h+1) for u,v,l,h,c in arcs]
    best=None;bestf=None
    for fs in itertools.product(*ranges):
        bal=[0]*n
        for (u,v,l,h,c),x in zip(arcs,fs):
            bal[u]+=x # out
            bal[v]-=x
        if any(bal): continue
        val=sum(c*x for (_,_,_,_,c),x in zip(arcs,fs))
        if best is None or val<best:
            best=val;bestf=fs
    return best,bestf

random.seed(1)
for trial in range(2000):
    n=random.randint(2,4)
    m=random.randint(2,7)
    arcs=[]
    for _ in range(m):
        u=random.randrange(n);v=random.randrange(n)
        while v==u: v=random.randrange(n)
        h=random.randint(0,2)
        l=random.randint(0,h)
        c=random.randint(-5,5)
        arcs.append((u,v,l,h,c))
    bf,bfs=brute(n,arcs)
    ns=NetworkSimplex(n,arcs,big_cost=1000000,inf_cap=100)
    try:
        ok=ns.solve()
    except Exception as e:
        print('EXC',trial,e,n,arcs,bf,bfs);break
    got=ns.objective()
    art=sum(ns.flow[i] for i in range(ns.n_real,len(ns.fr)))
    if bf is None:
        if art==0:
            print('unexpected feasible',trial,n,arcs,got);break
    else:
        if art!=0 or got!=bf:
            print('MISMATCH',trial,'n',n,'arcs',arcs,'bf',bf,bfs,'got',got,'art',art,'iters',ns.iters)
            for i in range(len(ns.fr)): print(i,ns.fr[i],ns.to[i],ns.lo[i],ns.hi[i],ns.cost[i],ns.flow[i],ns.basic[i])
            break
else:
    print('all ok')
